-- Учёт материалов: категории, справочник материалов, журнал движений, заявки на закупку.
-- Справочник и остатки загружены разово из рабочей Excel-таблицы студии.
-- Для категорий НЗ-запас (аккаунтская) и Материалы для МК дата последнего пересчёта
-- проставлена как 2026-10-02 (инвентаризация проведена в этот день со слов администратора).

CREATE TABLE public.material_categories (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE public.materials (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  category_id BIGINT REFERENCES public.material_categories(id),
  name TEXT NOT NULL,
  color_number TEXT,
  unit TEXT NOT NULL DEFAULT 'шт',
  qty_full NUMERIC NOT NULL DEFAULT 0,
  qty_half NUMERIC,
  qty_almost_empty NUMERIC,
  min_threshold NUMERIC,
  last_counted_at DATE,
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE public.material_transactions (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  material_id BIGINT NOT NULL REFERENCES public.materials(id) ON DELETE CASCADE,
  type TEXT NOT NULL, -- приход | расход | корректировка
  field TEXT NOT NULL DEFAULT 'qty_full', -- qty_full | qty_half | qty_almost_empty
  delta NUMERIC NOT NULL,
  comment TEXT,
  client_id BIGINT REFERENCES public.clients(id),
  created_by UUID,
  created_by_name TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE public.purchase_requests (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  cycle_label TEXT NOT NULL,
  material_id BIGINT REFERENCES public.materials(id),
  material_name_manual TEXT,
  needed_qty NUMERIC NOT NULL DEFAULT 0,
  available_qty NUMERIC,
  status TEXT NOT NULL DEFAULT 'новая', -- новая | заказано | куплено
  requested_by UUID,
  requested_by_name TEXT,
  note TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE public.material_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY "auth_all" ON public.material_categories FOR ALL TO authenticated USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.material_categories TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.material_categories TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.material_categories_id_seq TO authenticated;
GRANT USAGE, SELECT ON SEQUENCE public.material_categories_id_seq TO service_role;

